using VehicleRentalService.DTOs; using VehicleRentalService.Models; using System; using System.Linq; using System.Web.Http; using System.Data.Entity;
namespace VehicleRentalService.Controllers {
 [Authorize,RoutePrefix("api/rentals")] public class RentalsController:ApiController {
  VehicleRentalDbContext db=new VehicleRentalDbContext();
  [HttpGet,Route("")] public IHttpActionResult GetAll(){var q=db.Rentals.Include(x=>x.Vehicle).Include(x=>x.Customer).OrderByDescending(x=>x.StartDate).ToList();return Ok(q.Select(Map).ToList());}
  [HttpGet,Route("{id:int}")] public IHttpActionResult Get(int id){var x=db.Rentals.Include(r=>r.Vehicle).Include(r=>r.Customer).FirstOrDefault(r=>r.Id==id);if(x==null)return NotFound();return Ok(Map(x));}
  [HttpPost,Route("")] public IHttpActionResult Post(RentalCreateDto m){if(m==null||!ModelState.IsValid)return BadRequest(ModelState);if(m.EndDate.Date<m.StartDate.Date)return BadRequest("EndDate must be on or after StartDate.");var v=db.Vehicles.Find(m.VehicleId);if(v==null)return BadRequest("Invalid VehicleId.");if(!v.Available)return BadRequest("Vehicle is currently unavailable.");if(db.Customers.Find(m.CustomerId)==null)return BadRequest("Invalid CustomerId.");if(db.Rentals.Any(r=>r.VehicleId==m.VehicleId&&r.Status!=RentalStatus.Cancelled&&r.Status!=RentalStatus.Completed&&r.StartDate<m.EndDate&&r.EndDate>m.StartDate))return BadRequest("Vehicle is already reserved for this period.");var days=Math.Max(1,(m.EndDate.Date-m.StartDate.Date).Days);var x=new Rental{RentalNo="REN-"+DateTime.Now.ToString("yyyyMMddHHmmssfff"),VehicleId=m.VehicleId,CustomerId=m.CustomerId,StartDate=m.StartDate,EndDate=m.EndDate,TotalAmount=days*v.DailyRate,Notes=m.Notes};db.Rentals.Add(x);db.SaveChanges();return Created("api/rentals/"+x.Id,Map(x));}
  [HttpPut,Route("{id:int}")] public IHttpActionResult Put(int id,RentalCreateDto m){if(m==null||!ModelState.IsValid)return BadRequest(ModelState);var x=db.Rentals.Find(id);if(x==null)return NotFound();if(x.Status==RentalStatus.Completed||x.Status==RentalStatus.Cancelled)return BadRequest("Completed or cancelled rentals cannot be edited.");var v=db.Vehicles.Find(m.VehicleId);if(v==null)return BadRequest("Invalid VehicleId.");if(m.EndDate.Date<m.StartDate.Date)return BadRequest("EndDate must be on or after StartDate.");if(db.Rentals.Any(r=>r.Id!=id&&r.VehicleId==m.VehicleId&&r.Status!=RentalStatus.Cancelled&&r.Status!=RentalStatus.Completed&&r.StartDate<m.EndDate&&r.EndDate>m.StartDate))return BadRequest("Vehicle is already reserved for this period.");var days=Math.Max(1,(m.EndDate.Date-m.StartDate.Date).Days);x.VehicleId=m.VehicleId;x.CustomerId=m.CustomerId;x.StartDate=m.StartDate;x.EndDate=m.EndDate;x.TotalAmount=days*v.DailyRate;x.Notes=m.Notes;db.SaveChanges();return Ok(Map(x));}
  [HttpDelete,Route("{id:int}")] public IHttpActionResult Delete(int id){var x=db.Rentals.Find(id);if(x==null)return NotFound();db.Rentals.Remove(x);db.SaveChanges();return Ok(new{message="Rental deleted successfully."});}
  [HttpPut,Route("{id:int}/status")] public IHttpActionResult Status(int id,RentalStatus status){var x=db.Rentals.Find(id);if(x==null)return NotFound();x.Status=status;db.SaveChanges();return Ok(new{x.Id,x.Status});}
  static RentalDto Map(Rental x)=>new RentalDto{Id=x.Id,RentalNo=x.RentalNo,VehicleId=x.VehicleId,VehicleName=x.Vehicle?.Name,CustomerId=x.CustomerId,CustomerName=x.Customer?.Name,StartDate=x.StartDate,EndDate=x.EndDate,CreatedAt=x.CreatedAt,TotalAmount=x.TotalAmount,Status=x.Status,Notes=x.Notes};
  protected override void Dispose(bool d){if(d)db.Dispose();base.Dispose(d);}
 }
}
